def add(id,org,lab,region,year,date,topic,amount,url,group,fields,gaps,contact='',time='',sources=[]):
 p=dict(id=id,aliases=[],org=org,lab=lab,region=rank[region],year=year,date=date,time=time,status=['受理中·条件待核','已截止','线索待核'][group],topic=topic,amount=amount,url=url,kind='正式开放课题公告' if group<2 else '线索',fields=fields,personal='已知：南京信息工程大学现职、博士。'+('职称及限项、客座访问安排待本人确认；合作人由实验室获批后配备。' if id=='R001' else '其余个人条件按本条具体要求待本人确认；不代表已落实合作。'),gaps=gaps,contact=contact,relation='',sources=[url]+sources,value='经费、成果和权属分别见M/O/P列；具体缺口见S列。',amountlong=amount,screen_decision='保留' if group<2 else '待核',screen_reason=topic)
 p['details']=[id,p['kind'],org,lab,p['status'],year,date,time,topic,amount,*fields,p['personal'],gaps,url,'\n'.join(p['sources']),'2026-10-08（北京时间）','',p['value'],p['region'],contact,'']
 assert len(p['details'])==27
 D['projects'].append(p);D['groups'][group]['ids'].append(id);new.append(p)
 labels=['申请资格','合作及访问','经费使用及外拨','研究周期','成果数量及署名','知识产权','材料及提交方式']
 for k,v in zip(labels,fields):D['logs'].append([id,k,v,'\n'.join(p['sources']),'2026-10-08','官方正文/附件，缺口分别标记',p['screen_decision'],p['status']])
 for k,v in [('年度与受理',year+'；截止'+(date or '资料未取得')+' '+time),('任务筛选',topic),('金额',amount),('待手动核验',gaps)]:D['logs'].append([id,k,v,url,'2026-10-08',p['kind'],p['screen_decision'],p['status']])
